def count_vowels(string):
    vowels = set("aeiouAEIOU")
    return sum(
        char not in vowels
        and (
            (i > 0 and string[i - 1] in vowels)
            or (i + 1 < len(string) and string[i + 1] in vowels)
        )
        for i, char in enumerate(string)
    )
